import { describe, expect, it } from 'vitest'
import { alkalinityFromBicarbonate, alkalinityTitration, carbonateFractions, hardness, henryWithAir, langelier, mgLFromMoleFraction, phOfCo2Water, toCaCO3, ugLFromMoleFraction } from './chem'

describe('chem (TA T01–T04 oracles)', () => {
  it('ion → mg/L as CaCO3 reproduces the slide numbers', () => {
    expect(toCaCO3('ca', 95.2)).toBeCloseTo(238, 1)
    expect(toCaCO3('mg', 22)).toBeCloseTo(90.6, 1)
    expect(toCaCO3('na', 25.8)).toBeCloseTo(56.2, 0)
    expect(toCaCO3('cl', 67.8)).toBeCloseTo(95.6, 1)
    expect(toCaCO3('so4', 73)).toBeCloseTo(76, 0)
    expect(toCaCO3('co2', 5.5)).toBeCloseTo(12.5, 0)
    expect(toCaCO3('hco3', 200)).toBeCloseTo(164, 0)
  })
  it('hardness split of the split-treatment sheet: TH 328.6, NCH 130.6 = 40 (Ca) + 90.6 (Mg)', () => {
    const h = hardness({ ca: 238, mg: 90.6, alk: 198 })
    expect(h.th).toBeCloseTo(328.6, 1)
    expect(h.ch).toBe(198)
    expect(h.nch).toBeCloseTo(130.6, 1)
    expect(h.caNch).toBeCloseTo(40, 5)
    expect(h.mgNch).toBeCloseTo(90.6, 1)
  })
  it('TH below alkalinity: CH = TH, NCH = 0, the rest is Na2CO3 alkalinity', () => {
    const h = hardness({ ca: 100, mg: 50, alk: 200 })
    expect(h.ch).toBe(150)
    expect(h.nch).toBe(0)
    expect(h.excessAlk).toBe(50)
  })
  it('EXAMPLE T02-A, class way (pH counted): total 150, OH 5, CO3 100, HCO3 45', () => {
    const a = alkalinityTitration({ vol: 200, M: 30, P: 11, pH: 10 })
    expect(a.total).toBe(150)
    expect(a.oh).toBeCloseTo(5, 5)
    expect(a.mlOH).toBeCloseTo(1, 5)
    expect(a.co3).toBeCloseTo(100, 5)
    expect(a.hco3).toBeCloseTo(45, 5)
    expect(a.oh + a.co3 + a.hco3).toBeCloseTo(150, 5)
  })
  it('EXAMPLE T02-A, slide-rule way (OH ignored): CO3 110, HCO3 40', () => {
    const a = alkalinityTitration({ vol: 200, M: 30, P: 11 })
    expect(a.co3).toBe(110)
    expect(a.hco3).toBe(40)
    expect(a.rule).toContain('P < M/2')
  })
  it('2020-21 Q8(b): 105 mg/L HCO3, pH 10.3 → alkalinity 268, CH 268, NCH 42', () => {
    const a = alkalinityFromBicarbonate({ hco3mgL: 105, pH: 10.3, pK2: 10.3, th: 310 })
    expect(a.ratio).toBeCloseTo(1, 6)
    expect(a.hco3).toBeCloseTo(86.07, 1)
    expect(a.co3).toBeCloseTo(172.1, 0)
    expect(a.oh).toBeCloseTo(9.98, 1)
    expect(a.total).toBeCloseTo(268.1, 0)
    expect(a.ch).toBeCloseTo(268.1, 0)
    expect(a.nch).toBeCloseTo(41.9, 0)
  })
  it('carbonate fractions: equal HCO3/H2CO3 at pK1, equal HCO3/CO3 at pK2, sum 1', () => {
    const f = carbonateFractions(6.3)
    expect(f.a0).toBeCloseTo(f.a1, 3)
    const g = carbonateFractions(10.3)
    expect(g.a1).toBeCloseTo(g.a2, 3)
    expect(f.a0 + f.a1 + f.a2).toBeCloseTo(1, 10)
  })
  it('EXAMPLE T04-C (class numbers 6.84e-8): 500 µg/L; with 0.01 mol air X = 5.8e-8, 75.7 µg/L left', () => {
    expect(ugLFromMoleFraction(6.84e-8, 131.4)).toBeCloseTo(499.7, 0)
    const r = henryWithAir({ x: 6.84e-8, H: 560, nAir: 0.01, mw: 131.4 })
    expect(r.X).toBeCloseTo(5.8e-8, 9)
    expect(r.xLeft).toBeCloseTo(1.04e-8, 10)
    expect(r.ugLLeft).toBeCloseTo(75.7, 0)
  })
  it('2023-24 Q1(b) (6.9e-8): 504 µg/L, 76.4 µg/L left', () => {
    expect(mgLFromMoleFraction(6.9e-8, 131.4)).toBeCloseTo(0.5041, 3)
    const r = henryWithAir({ x: 6.9e-8, H: 560, nAir: 0.01, mw: 131.4 })
    expect(r.ugLLeft).toBeCloseTo(76.4, 0)
    expect(r.fractionLeft).toBeCloseTo(100 / 660, 6)
  })
  it('2023-24 Q2(b): CO2 at 2 atm, K_H = 0.033363 → [H2CO3*] 0.0667 M, pH ≈ 3.74', () => {
    const r = phOfCo2Water({ KH: 0.033363, P: 2 })
    expect(r.h2co3).toBeCloseTo(0.066726, 6)
    expect(r.pH).toBeCloseTo(3.74, 2)
    expect(r.approxPH).toBeCloseTo(r.pH, 2)
  })
  it('2012-13 Q1(c): pHs 8.105, LSI −0.105, RSI 8.21', () => {
    const l = langelier({ pH: 8, pK2minusPKs: 2.54, caMgL: 60, alkCaCO3: 91 })
    expect(l.pHs).toBeCloseTo(8.105, 2)
    expect(l.lsi).toBeCloseTo(-0.105, 2)
    expect(l.rsi).toBeCloseTo(8.21, 2)
  })
})
